import { chromium } from '/kos_ulan/huangli/work/project/huangli_tools/officecli/.agents/skills/pptx-craft/node_modules/playwright/index.mjs';
const dir='/kos_ulan/huangli/work/project/huangli_tools/officecli/output/sample_top10/codex/qwen3.8-max/pptx-craft/01/pass1/output/pages';
const b=await chromium.launch();
for (const p of [9,10,2]) {
  const pg=await b.newPage({viewport:{width:1400,height:900}});
  await pg.goto('file://'+dir+'/page-'+p+'.pptx.html');
  await pg.waitForTimeout(2500);
  const r=await pg.evaluate(()=>{
    const main=document.querySelector('main');
    const out={mainH:main?.getBoundingClientRect().height, mainTop:main?.getBoundingClientRect().top};
    const content=document.querySelector('[data-pptx-role=\"content\"]');
    out.contentH=content?.getBoundingClientRect().height;
    out.kids=[...content.children].map(c=>({cls:c.className.slice(0,80),h:+c.getBoundingClientRect().height.toFixed(1),top:+c.getBoundingClientRect().top.toFixed(1)}));
    if(document.querySelector('.grid.grid-cols-6')){
      out.cards=[...document.querySelectorAll('.grid.grid-cols-6 > div')].map(c=>{
        const cr=c.getBoundingClientRect();
        const inner=[...c.children].reduce((a,ch)=>a+ch.getBoundingClientRect().height,0);
        return {h:+cr.height.toFixed(1), innerH:+inner.toFixed(1), text:c.textContent.trim().slice(0,14)};
      });
    }
    return out;
  });
  console.log('=== page-'+p, JSON.stringify(r,null,1));
  await pg.close();
}
await b.close();
EOF
